async function saveHandoverNote(e){e.preventDefault();if(isViewer())return toast('조회자 계정은 메모를 작성할 수 없습니다.');const content=new FormData(e.currentTarget).get('content').trim();if(!content)return toast('메모 내용을 입력하세요.');if(content.length>500)return toast('메모는 500자 이내로 작성하세요.');try{if(API_URL){const r=await api('createHandoverNote',{token:state.session.token,content,site:state.site});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}else{if((state.data.handoverNotes||[]).length>=200)return toast('공유 메모는 최대 200건까지 보관됩니다.');state.data.handoverNotes.unshift({id:uid('handover-note'),site:state.site,authorUserId:state.session.id,authorName:state.session.name,content,createdAt:new Date().toISOString()});if(!await save())return;}toast('공유 메모를 등록했습니다.');render();}catch(err){toast(err.message||'공유 메모 등록에 실패했습니다.');}}
