async function saveStudent(e){e.preventDefault();const f=new FormData(e.currentTarget),id=e.currentTarget.dataset.id,old=studentById(id),record={...old,id:id||uid('student'),name:f.get('name').trim(),site:f.get('site'),type:f.get('type').trim(),studentNumber:f.get('studentNumber').trim(),phone:f.get('phone').trim(),email:f.get('email').trim(),color:f.get('color'),active:f.get('active')==='true',semesterIds:old?.semesterIds||[activeSemester().id]};const term=activeSemester().id;record.semesterIds=[...(record.semesterIds||[])];record.participationEndDates={...(old?.participationEndDates||{})};if(f.get('participating')==='true'){if(!record.semesterIds.includes(term))record.semesterIds.push(term);if(f.get('participationEnd'))record.participationEndDates[term]=f.get('participationEnd');else delete record.participationEndDates[term];}else if(record.semesterIds.includes(term))record.participationEndDates[term]=f.get('participationEnd')||iso(new Date());if(id)state.data.students[state.data.students.findIndex(s=>s.id===id)]=record;else state.data.students.push(record);state.site=record.site;if(!await save())return;closeModal();toast('학생 정보를 저장했습니다.');render();}
function compressProfilePhoto(file){return new Promise((resolve,reject)=>{if(!file||!['image/jpeg','image/png'].includes(file.type))return reject(Error('JPG 또는 PNG 파일을 선택하세요.'));if(file.size>8*1024*1024)return reject(Error('8MB 이하 사진만 선택할 수 있습니다.'));const reader=new FileReader();reader.onerror=()=>reject(Error('사진을 읽을 수 없습니다.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(Error('올바른 이미지 파일이 아닙니다.'));image.onload=()=>{const max=480,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const dataUrl=canvas.toDataURL('image/jpeg',0.82);if(dataUrl.length>680000)return reject(Error('사진 용량이 큽니다. 더 작은 사진을 선택하세요.'));resolve(dataUrl);};image.src=reader.result;};reader.readAsDataURL(file);});}
async function saveProfilePhoto(e){e.preventDefault();if(state.session.role!=='student')return toast('학생 계정만 사진을 등록할 수 있습니다.');const file=new FormData(e.currentTarget).get('photo');try{const dataUrl=await compressProfilePhoto(file);if(API_URL){const r=await api('studentUploadProfilePhoto',{token:state.session.token,photo:{dataUrl}});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}else currentStudent().hasProfilePhoto=true;state.photoUrls[currentStudentId()]=dataUrl;state.photoLoads[currentStudentId()]=true;closeModal();toast('증명사진을 안전하게 저장했습니다.');render();}catch(err){toast(err.message||'사진을 저장하지 못했습니다.');}}
async function fetchProfilePhoto(studentId){if(!API_URL)return state.photoUrls[studentId]||'';const r=await api('getProfilePhoto',{token:state.session.token,studentId});if(!r.ok)throw Error(r.error);return r.dataUrl||'';}
function loadPhotoIfNeeded(student){if(!student?.hasProfilePhoto||state.photoUrls[student.id]||state.photoLoads[student.id])return;state.photoLoads[student.id]=true;fetchProfilePhoto(student.id).then(url=>{if(url){state.photoUrls[student.id]=url;render();}}).catch(()=>{state.photoLoads[student.id]=false;});}
function loadStudentThumbnails(){students().filter(s=>s.hasProfilePhoto).forEach(student=>{const target=document.querySelector(`[data-photo-thumb="${student.id}"]`);if(state.photoUrls[student.id]&&target)target.outerHTML=`<img data-photo-thumb="${student.id}" class="avatar small profile-photo" src="${state.photoUrls[student.id]}" alt="${esc(student.name)} 증명사진">`;else if(!state.photoLoads[student.id]){state.photoLoads[student.id]=true;fetchProfilePhoto(student.id).then(url=>{if(url){state.photoUrls[student.id]=url;const el=document.querySelector(`[data-photo-thumb="${student.id}"]`);if(el)el.outerHTML=`<img data-photo-thumb="${student.id}" class="avatar small profile-photo" src="${url}" alt="${esc(student.name)} 증명사진">`;}}).catch(()=>{state.photoLoads[student.id]=false;});}});}
async function showStudentDetail(studentId){const student=studentById(studentId);if(!student)return;let photo=state.photoUrls[student.id]||'';if(isAdmin()&&student.hasProfilePhoto&&!photo){try{photo=await fetchProfilePhoto(student.id);if(photo)state.photoUrls[student.id]=photo;}catch(err){return toast(err.message||'사진을 불러오지 못했습니다.');}}showModal(studentDetailModal(student,photo));}
async function saveSchedule(e){e.preventDefault();const f=new FormData(e.currentTarget),id=e.currentTarget.dataset.id;if(mins(f.get('end'))<=mins(f.get('start')))return toast('종료시간은 시작시간보다 늦어야 합니다.');const student=studentById(f.get('studentId')),record={id:id||uid('schedule'),site:f.get('site'),semesterId:activeSemester().id,studentId:student.id,studentName:student.name,periodType:f.get('periodType'),kind:f.get('kind'),weekday:Number(f.get('weekday')),date:f.get('date'),start:f.get('start'),end:f.get('end')};if(record.kind==='weekly')delete record.date;else delete record.weekday;if(id)state.data.schedules[state.data.schedules.findIndex(s=>s.id===id)]=record;else state.data.schedules.push(record);state.site=record.site;if(!await save())return;closeModal();toast('근무 일정을 저장했습니다.');render();}
async function saveException(e){e.preventDefault();const f=new FormData(e.currentTarget),type=f.get('type'),schedule=state.data.schedules.find(s=>s.id===f.get('scheduleId')),student=type==='add'?studentById(f.get('studentId')):studentById(schedule?.studentId);if(!student)return toast('대상 학생을 선택하세요.');if(type!=='cancel'&&mins(f.get('end'))<=mins(f.get('start')))return toast('종료시간은 시작시간보다 늦어야 합니다.');state.data.exceptions.push({id:uid('exception'),semesterId:activeSemester().id,site:state.site,type,date:f.get('date'),scheduleId:type==='add'?'':schedule.id,studentId:student.id,studentName:student.name,start:f.get('start'),end:f.get('end'),reason:f.get('reason').trim()});if(!await save())return;closeModal();toast('예외 일정을 저장했습니다.');render();}
async function saveAccount(e){e.preventDefault();const f=new FormData(e.currentTarget),current=state.data.accounts.find(a=>a.id===e.currentTarget.dataset.id),role=f.get('role'),studentId=role==='student'?f.get('studentId'):'';if(role==='student'&&!studentId)return toast('학생 로그인 계정은 연결할 학생을 선택하세요. 학생 등록 자체는 계정 없이 가능합니다.');const user={id:current?.id,name:f.get('name').trim(),username:f.get('username').trim(),role,studentId,password:f.get('password'),active:f.get('active')==='true'};if(API_URL){try{const r=await api('adminUpsertUser',{token:state.session.token,user});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}catch(err){return toast(err.message);}}else{user.id=user.id||uid('account');state.data.accounts=state.data.accounts.filter(a=>a.id!==user.id).concat(user);if(!await save())return;}closeModal();toast('계정을 저장했습니다.');render();}
async function saveSimple(e){e.preventDefault();const f=new FormData(e.currentTarget),key=e.currentTarget.dataset.kind==='notice'?'notices':'handovers';state.data[key].unshift({id:uid(key.slice(0,-1)),semesterId:activeSemester().id,site:f.get('site'),title:f.get('title').trim(),content:f.get('content').trim(),url:f.get('url')||'',important:f.get('important')==='true',author:state.session.name,createdAt:new Date().toISOString(),readBy:[],requiresRead:key==='notices'});if(!await save())return;closeModal();toast(key==='notices'?'공지를 등록했습니다.':'인수인계를 등록했습니다.');render();}

async function saveClassSchedule(e){e.preventDefault();const f=new FormData(e.currentTarget),item={id:e.currentTarget.dataset.id,semesterId:activeSemester().id,weekday:Number(f.get('weekday')),start:f.get('start'),end:f.get('end'),subject:f.get('subject')};try{const r=await api('studentUpsertClassSchedule',{token:state.session.token,item});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);closeModal();toast('수업시간표를 저장했습니다.');render();}catch(err){toast(err.message);}}
async function deleteClassSchedule(itemId){if(!confirm('이 수업을 삭제할까요?'))return;try{const r=await api('studentDeleteClassSchedule',{token:state.session.token,itemId});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);toast('수업을 삭제했습니다.');render();}catch(err){toast(err.message);}}
async function saveWorkPreference(e){e.preventDefault();const f=new FormData(e.currentTarget),item={id:e.currentTarget.dataset.id,date:f.get('date'),start:f.get('start'),end:f.get('end')};try{const r=await api('studentUpsertWorkPreference',{token:state.session.token,item});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);closeModal();toast('희망근무를 저장했습니다.');render();}catch(err){toast(err.message);}}
async function deleteWorkPreference(itemId){if(!confirm('희망근무 신청을 취소할까요?'))return;try{const r=await api('studentDeleteWorkPreference',{token:state.session.token,itemId});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);toast('희망근무를 취소했습니다.');render();}catch(err){toast(err.message);}}
async function createScheduleDraft(dataset){try{const item={semesterId:activeSemester().id,site:state.site,studentId:dataset.createDraft,date:dataset.date,start:dataset.start,end:dataset.end},r=await api('adminUpsertScheduleDraft',{token:state.session.token,item});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);closeModal();showModal(plannerDayModal(item.date));toast('Draft에 배정했습니다.');}catch(err){toast(err.message);}}
async function deleteScheduleDraft(itemId){try{const date=state.data.scheduleDrafts.find(x=>x.id===itemId)?.date,r=await api('adminDeleteScheduleDraft',{token:state.session.token,itemId});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);closeModal();showModal(plannerDayModal(date));toast('Draft 배정을 취소했습니다.');}catch(err){toast(err.message);}}
async function confirmScheduleDraft(itemId){if(!confirm('이 Draft를 실제 근무로 최종 확정할까요?'))return;try{const date=state.data.scheduleDrafts.find(x=>x.id===itemId)?.date,r=await api('adminConfirmScheduleDraft',{token:state.session.token,itemId});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);closeModal();showModal(plannerDayModal(date));toast('실제 근무표에 확정했습니다.');}catch(err){toast(err.message);}}
async function saveSwap(e){e.preventDefault();const f=new FormData(e.currentTarget),schedule=state.data.schedules.find(s=>s.id===f.get('scheduleId')),swap={scheduleId:schedule.id,site:schedule.site,semesterId:activeSemester().id,requesterStudentId:currentStudentId(),date:f.get('date'),reason:f.get('reason').trim()};if(API_URL){try{const r=await api('studentCreateSwap',{token:state.session.token,swap});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}catch(err){return toast(err.message);}}else{state.data.swaps.unshift({id:uid('swap'),...swap,requesterId:state.session.id,requesterName:state.session.name,status:'모집중',applicants:[],adminNote:'',createdAt:new Date().toISOString()});if(!await save())return;}closeModal();toast('대타 모집을 시작했습니다.');render();}
async function takeSwap(id){if(!confirm('이 대타를 가져가겠다고 신청할까요?'))return;if(API_URL){try{const r=await api('studentApplySwap',{token:state.session.token,swapId:id});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}catch(err){return toast(err.message);}}else{const item=state.data.swaps.find(s=>s.id===id),student=currentStudent(),event=eventsForDate(state.data,item.site,fromIso(item.date),item.semesterId).find(x=>x.id===item.scheduleId);if(item.site!==student.site)return toast('다른 근무지의 대타는 신청할 수 없습니다.');if(!event)return toast('대상 근무를 찾을 수 없습니다.');if(hasTimeConflict(state.data,student.id,item.date,event.start,event.end))return toast('기존 근무와 시간이 겹칩니다.');item.applicants=item.applicants||[];if(item.applicants.some(a=>a.studentId===student.id))return toast('이미 신청한 대타입니다.');item.applicants.push({studentId:student.id,name:student.name,appliedAt:new Date().toISOString()});if(!await save())return;}toast('대타 가져가기를 신청했습니다.');render();}
async function saveSwapReview(e){e.preventDefault();const f=new FormData(e.currentTarget),id=e.currentTarget.dataset.id,payload={swapId:id,status:f.get('status'),assigneeId:f.get('assigneeId'),note:f.get('note')};if(API_URL){try{const r=await api('adminUpdateSwap',{token:state.session.token,...payload});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}catch(err){return toast(err.message);}}else{const s=state.data.swaps.find(x=>x.id===id),assignee=studentById(payload.assigneeId);Object.assign(s,{status:payload.status,adminNote:payload.note,assigneeId:assignee?.id||'',assigneeName:assignee?.name||'',updatedAt:new Date().toISOString()});if(!await save())return;}closeModal();toast('대타 요청을 처리했습니다.');render();}
async function saveBudget(e){e.preventDefault();if(!isAdmin())return toast('관리자만 예산을 수정할 수 있습니다.');const f=new FormData(e.currentTarget),budget={semesterId:activeSemester().id,site:f.get('site'),workType:f.get('workType'),total:Number(f.get('total')),wage:Number(f.get('wage'))};try{if(API_URL){const r=await api('adminUpdateBudget',{token:state.session.token,budget});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}else{const entry=activeSemester().budgets[budget.site].byWorkType[budget.workType],before=structuredClone(entry);Object.assign(entry,{total:budget.total,wage:budget.wage});state.data.budgetAudit.unshift({id:uid('budget-audit'),semesterId:budget.semesterId,site:budget.site,workType:budget.workType,before,after:structuredClone(entry),adminId:state.session.id,adminName:state.session.name,createdAt:new Date().toISOString()});if(!await save())return;}closeModal();toast('예산 설정과 변경 이력을 저장했습니다.');render();}catch(err){toast(err.message);}}
async function saveSemester(e){e.preventDefault();const f=new FormData(e.currentTarget),existing=state.data.semesters.find(s=>s.id===e.currentTarget.dataset.id);if(f.get('endDate')<f.get('startDate'))return toast('종료일은 시작일 이후여야 합니다.');if((f.get('termEndDate')||f.get('vacationStartDate'))&&(!f.get('termEndDate')||!f.get('vacationStartDate')||f.get('vacationStartDate')<=f.get('termEndDate')))return toast('종강일과 방학 시작일을 순서대로 모두 설정하세요.');const id=existing?.id||uid('semester'),record={...existing,id,name:f.get('name').trim(),startDate:f.get('startDate'),endDate:f.get('endDate'),termEndDate:f.get('termEndDate'),vacationStartDate:f.get('vacationStartDate'),termWeeklyLimit:Number(f.get('termWeeklyLimit')),vacationWeeklyLimit:Number(f.get('vacationWeeklyLimit')),mixedWeekPolicy:'SEPARATE_PERIOD_LIMITS',vacationHours:{general:{start:f.get('generalVacationStart'),end:f.get('generalVacationEnd')},holmz:{start:f.get('holmzVacationStart'),end:f.get('holmzVacationEnd')}},active:existing?.active||false,budgets:existing?.budgets||{general:{total:0,wage:0,rates:{},byWorkType:{}},holmz:{total:0,wage:0,rates:{},byWorkType:{}}}};if(existing)state.data.semesters[state.data.semesters.indexOf(existing)]=record;else{state.data.semesters.push(record);state.viewingSemesterId=id;if(f.get('copyStudents')==='true')state.data.students.forEach(s=>{s.semesterIds=[...(s.semesterIds||[]),id];});}if(!await save())return;closeModal();toast(existing?'학기 운영 설정을 저장했습니다.':'새 학기를 생성했습니다. 일정은 비어 있습니다.');render();}
async function copyTermSchedulesToVacation(){if(!isAdmin())return toast('관리자만 시간표를 복사할 수 있습니다.');const source=semesterRecords(state.data.schedules).filter(s=>s.site===state.site&&s.periodType==='TERM'&&s.kind==='weekly'),existing=semesterRecords(state.data.schedules).filter(s=>s.site===state.site&&s.periodType==='VACATION');const copies=source.filter(s=>!existing.some(v=>v.studentId===s.studentId&&v.kind==='weekly'&&v.weekday===s.weekday&&v.start===s.start&&v.end===s.end)).map(s=>({...s,id:uid('schedule'),periodType:'VACATION'}));if(!copies.length)return toast('복사할 새 학기중 정기 일정이 없습니다.');if(!confirm(`${copies.length}개 학기중 정기 일정을 방학 시간표 후보로 복사할까요? 방학 운영시간과 주간 한도 검증을 거칩니다.`))return;state.data.schedules.push(...copies);if(!await save())return;toast('학기중 정기 일정을 방학 시간표로 복사했습니다.');render();}
async function activateSemester(id){if(!confirm('선택한 학기로 전환할까요?'))return;state.data.settings.activeSemesterId=id;state.data.semesters.forEach(s=>s.active=s.id===id);if(!await save())return;render();}
async function readNotice(id){const n=state.data.notices.find(x=>x.id===id);if(n){n.readBy=n.readBy||[];if(!n.readBy.includes(state.session.id))n.readBy.push(state.session.id);}if(API_URL){try{const r=await api('studentMarkNoticeRead',{token:state.session.token,noticeId:id});if(!r.ok)throw Error(r.error);}catch(e){return toast('확인 저장 실패 — '+e.message);}}else if(!await save())return;toast('공지 확인 처리했습니다.');render();}
async function deleteRecord(key,id){if(!confirm('이 항목을 삭제할까요?'))return;state.data[key]=state.data[key].filter(x=>x.id!==id);if(!await save())return;render();}
async function deleteAccount(id){if(!confirm('이 계정을 삭제할까요?'))return;if(API_URL){try{const r=await api('adminDeleteUser',{token:state.session.token,userId:id});if(!r.ok)throw Error(r.error);state.data=normalizeData(r.data);}catch(err){return toast(err.message);}}else{state.data.accounts=state.data.accounts.filter(a=>a.id!==id);if(!await save())return;}render();}
async function deleteStudent(id){const s=studentById(id);if(!confirm(`${s.name} 학생을 비활성화할까요? 과거 일정은 유지됩니다.`))return;s.active=false;if(!await save())return;render();}
async function deleteSchedule(id){const item=state.data.schedules.find(s=>s.id===id);if(!item||!confirm(`${item.studentName}의 일정을 삭제할까요?`))return;state.data.schedules=state.data.schedules.filter(s=>s.id!==id);if(!await save())return;render();}


async function login(e){e.preventDefault();if(!API_URL)return toast('공용 로그인 API가 설정되지 않았습니다.');const f=new FormData(e.currentTarget);try{const r=await api('login',{username:f.get('username'),password:f.get('password')});if(!r.ok)throw Error(r.error);state.session={...r.user,token:r.token};state.data=normalizeData(r.data);if(state.session.role==='student'){const student=currentStudent();if(!student)throw Error('연결된 학생 정보를 찾을 수 없습니다.');state.site=student.site;}state.view='home';sessionStorage.setItem(`${DB_KEY}:token`,r.token);render();}catch(err){toast(err.message||'로그인에 실패했습니다.');}}
async function logout(){if(API_URL&&state.session?.token)api('logout',{token:state.session.token});sessionStorage.removeItem(`${DB_KEY}:token`);localStorage.removeItem(DB_KEY);state.savedData=null;state.photoUrls={};state.photoLoads={};state.viewingSemesterId='';state.session=null;state.data=null;state.view='home';render();}
if(typeof document!=='undefined'){(async()=>{try{if(API_URL){const token=sessionStorage.getItem(`${DB_KEY}:token`);if(token){const r=await api('session',{token});if(r.ok){state.session={...r.user,token};state.data=normalizeData(r.data);}}if(!state.session){render();return;}}else{state.data=await loadData();const previewStudent=PREVIEW_STUDENT_ID&&state.data.students.find(s=>s.id===PREVIEW_STUDENT_ID);state.session=previewStudent?{id:`preview-${previewStudent.id}`,name:previewStudent.name,role:'student',studentId:previewStudent.id}:{id:'local-admin',name:'검토용 관리자',role:'admin',studentId:''};}render();}catch(err){document.querySelector('#app').innerHTML=`<p class="fatal">데이터를 불러오지 못했습니다. ${esc(err.message)}</p>`;}})();}
